static void put_be32(std::vector<uint8_t>& d, uint32_t v) {
    for (int i = 3; i >= 0; --i) d.push_back(uint8_t(v >> (8 * i)));
}
static void put_le16(std::vector<uint8_t>& d, uint32_t v) {
    d.push_back(uint8_t(v));
    d.push_back(uint8_t(v >> 8));
}
static void put_le32(std::vector<uint8_t>& d, uint32_t v) {
    for (int i = 0; i < 4; ++i) d.push_back(uint8_t(v >> (8 * i)));
}
static uint32_t get_le32(const std::vector<uint8_t>& d, size_t o) {
    return uint32_t(d[o]) | uint32_t(d[o + 1]) << 8 | uint32_t(d[o + 2]) << 16 | uint32_t(d[o + 3]) << 24;
}

// raw deflate made of stored blocks (a valid deflate stream any inflater reads)
static std::vector<uint8_t> deflate_stored(const std::vector<uint8_t>& data) {
    std::vector<uint8_t> out;
    size_t at = 0;
    do {
        const size_t n = std::min<size_t>(65535, data.size() - at);
        const bool last = at + n >= data.size();
        out.push_back(last ? 1 : 0);
        put_le16(out, uint32_t(n));
        put_le16(out, uint32_t(~n & 0xFFFF));
        out.insert(out.end(), data.begin() + std::ptrdiff_t(at), data.begin() + std::ptrdiff_t(at + n));
        at += n;
    } while (at < data.size());
    return out;
}

// RGBA PNG (8 bits per channel, filter 0, zlib with stored blocks)
static std::vector<uint8_t> png(const Rgba& img) {
    std::vector<uint8_t> raw;
    raw.reserve(size_t(img.h) * (size_t(img.w) * 4 + 1));
    for (int y = 0; y < img.h; ++y) {
        raw.push_back(0);
        const uint8_t* row = img.at(0, y);
        raw.insert(raw.end(), row, row + size_t(img.w) * 4);
    }
    std::vector<uint8_t> z = {0x78, 0x01};
    std::vector<uint8_t> d = deflate_stored(raw);
    z.insert(z.end(), d.begin(), d.end());
    uint32_t a = 1, b = 0;
    for (uint8_t c : raw) {
        a = (a + c) % 65521;
        b = (b + a) % 65521;
    }
    put_be32(z, (b << 16) | a);
    std::vector<uint8_t> out = {0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A};
    auto chunk = [&out](const char* type, const std::vector<uint8_t>& data) {
        put_be32(out, uint32_t(data.size()));
        std::vector<uint8_t> td(type, type + 4);
        td.insert(td.end(), data.begin(), data.end());
        out.insert(out.end(), td.begin(), td.end());
        put_be32(out, kits::crc32(td.data(), td.size()));
    };
    std::vector<uint8_t> ihdr;
    put_be32(ihdr, uint32_t(img.w));
    put_be32(ihdr, uint32_t(img.h));
    ihdr.insert(ihdr.end(), {8, 6, 0, 0, 0});
    chunk("IHDR", ihdr);
    chunk("IDAT", z);
    chunk("IEND", {});
    return out;
}

struct File {
    std::string name;
    std::vector<uint8_t> data;
};
static std::vector<uint8_t> bytes_of(const std::string& s) { return std::vector<uint8_t>(s.begin(), s.end()); }

// A zip: stored entries, or deflate (stored blocks); flags (bit 0 = encrypted) and a wrong CRC on request
static std::vector<uint8_t> zip(const std::vector<File>& files, bool deflate = false, uint16_t flags = 0, const std::string& bad_crc = "") {
    std::vector<uint8_t> out, cd;
    for (const File& f : files) {
        const std::vector<uint8_t> body = deflate ? deflate_stored(f.data) : f.data;
        uint32_t crc = kits::crc32(f.data.data(), f.data.size());
        if (f.name == bad_crc) crc ^= 0x5A5A5A5Au;
        const uint32_t lho = uint32_t(out.size());
        put_le32(out, 0x04034b50u);
        put_le16(out, 20);
        put_le16(out, flags);
        put_le16(out, deflate ? 8 : 0);
        put_le16(out, 0);
        put_le16(out, 0x21);
        put_le32(out, crc);
        put_le32(out, uint32_t(body.size()));
        put_le32(out, uint32_t(f.data.size()));
        put_le16(out, uint32_t(f.name.size()));
        put_le16(out, 0);
        out.insert(out.end(), f.name.begin(), f.name.end());
        out.insert(out.end(), body.begin(), body.end());
        put_le32(cd, 0x02014b50u);
        put_le16(cd, 20);
        put_le16(cd, 20);
        put_le16(cd, flags);
        put_le16(cd, deflate ? 8 : 0);
        put_le16(cd, 0);
        put_le16(cd, 0x21);
        put_le32(cd, crc);
        put_le32(cd, uint32_t(body.size()));
        put_le32(cd, uint32_t(f.data.size()));
        put_le16(cd, uint32_t(f.name.size()));
        put_le16(cd, 0);
        put_le16(cd, 0);
        put_le16(cd, 0);
        put_le16(cd, 0);
        put_le32(cd, 0);
        put_le32(cd, lho);
        cd.insert(cd.end(), f.name.begin(), f.name.end());
    }
    const uint32_t cd_off = uint32_t(out.size());
    out.insert(out.end(), cd.begin(), cd.end());
    put_le32(out, 0x06054b50u);
    put_le16(out, 0);
    put_le16(out, 0);
    put_le16(out, uint32_t(files.size()));
    put_le16(out, uint32_t(files.size()));
    put_le32(out, uint32_t(cd.size()));
    put_le32(out, cd_off);
    put_le16(out, 0);
    return out;
}

static void write(const fs::path& p, const std::vector<uint8_t>& b) {
    fs::create_directories(p.parent_path());
    std::ofstream(p, std::ios::binary | std::ios::trunc).write(reinterpret_cast<const char*>(b.data()), std::streamsize(b.size()));
}

// FC 27's kit spec scaled down 16 times (jersey colour 128, decal coeff 8): the same roles, formats and checks
static const std::vector<kits::TexSpec>& small_spec() {
    static const std::vector<kits::TexSpec> v = [] {
        std::vector<kits::TexSpec> s = kits::fc27_kit_spec();
        for (auto& t : s) {
            t.w /= 16;
            t.h /= 16;
        }
        return s;
    }();
    return v;
}

static const char* kSettings = R"({
   "jerseycollargeometrytype": 2,
   "teamcolorprim": "#234f8e",
   "teamcolorprimpercent": "100",
   "teamcolorsec": "#ffd700",
   "teamcolorsecpercent": "60",
   "teamcolortert": "#234f8e",
   "teamcolortertpercent": "100",
   "jerseynamecolor": "#e8e8e8",
   "jerseynameoutlinecolor": "#234f8e",
   "jerseynumbercolorprim": "#e8e8e8",
   "jerseynumbercolorsec": "#234f8e",
   "jerseynumbercolorter": "#234f8e",
   "shortsnumbercolorprim": "#e8e8e8",
   "shortsnumbercolorsec": "#234f8e",
   "shortsnumbercolorter": "#234f8e",
   "jerseynamelayouttype": 1,
   "shortstyle": 0
})";

struct Opts {
    bool decals = true;          // the 12 brand / crest textures
    bool blank = false;          // blank.png (the zips without decals have one)
    int decal_factor = 1;        // decals 2x the game's size (most real zips: 512 for a 256 texture)
    std::string skip;            // a texture left out ("jersey_normal")
    std::string bad_png;         // a texture that is not a PNG
    std::string wrong_size;      // a texture 4 pixels too wide
    bool settings = true;
    std::string settings_text = kSettings;
    bool minikit = true;
    bool extra = false;          // readme.txt in the zip
    bool solid_only = false;     // one colour per texture (fast full-size zips)
};

// the colour of a texture role (each role its own, so a staged file shows which picture it came from)
static void role_colour(size_t i, uint8_t c[4]) {
    c[0] = uint8_t(20 + 9 * i);
    c[1] = uint8_t(230 - 7 * i);
    c[2] = uint8_t(60 + 5 * i);
    c[3] = 255;
}

static std::vector<File> kit_files(const std::vector<kits::TexSpec>& spec, const Opts& o) {
    std::vector<File> f;
    for (size_t i = 0; i < spec.size(); ++i) {
        const kits::TexSpec& t = spec[i];
        if ((t.decal && !o.decals) || t.role == o.skip) continue;
        // real zips: decal colour / normal at twice the game's size, decal coeff at the game's
        const int fac = t.decal && t.role.find("_coeff") == std::string::npos ? o.decal_factor : 1;
        int w = t.w * fac, h = t.h * fac;
        if (t.role == o.wrong_size) w += 4;
        uint8_t c[4];
        role_colour(i, c);
        Rgba img = solid(w, h, c[0], c[1], c[2], c[3]);
        if (t.role == "jersey_color" && !o.solid_only)  // left half red, right half blue (the thumbnail)
            for (int y = 0; y < h; ++y)
                for (int x = 0; x < w; ++x) {
                    uint8_t* p = img.at(x, y);
                    const bool left = x < w / 2;
                    p[0] = left ? 255 : 0;
                    p[1] = 0;
                    p[2] = left ? 0 : 255;
                }
        f.push_back({t.role + ".png", t.role == o.bad_png ? bytes_of("this is not a PNG file") : png(img)});
    }
    if (o.minikit) {
        Rgba m = solid(32, 32, 0, 200, 0);
        for (int y = 0; y < 32; ++y)
            for (int x = 16; x < 32; ++x) {
                uint8_t* p = m.at(x, y);
                p[0] = 255;
                p[1] = 255;
                p[2] = 255;
            }
        f.push_back({"minikit.png", png(m)});
    }
    if (o.settings) f.push_back({"settings.json", bytes_of(o.settings_text)});
    f.push_back({"hotspots.hotspot", bytes_of(R"({"HotspotFormatVersion": 1, "Hotspots": [{"Group": "jersey", "Name": "numberback"}]})")});
    if (o.blank) f.push_back({"blank.png", png(solid(16, 16, 0, 0, 0, 0))});
    if (o.extra) f.push_back({"readme.txt", bytes_of("made with a kit creator")});
    return f;
}

static fs::path make_kit_zip(const fs::path& p, const std::vector<kits::TexSpec>& spec, const Opts& o = Opts()) {
    write(p, zip(kit_files(spec, o)));
    return p;
}

static int max_diff(const Rgba& a, const Rgba& b, int channels = 4) {
    if (a.w != b.w || a.h != b.h) return 999;
    int m = 0;
    for (int y = 0; y < a.h; ++y)
        for (int x = 0; x < a.w; ++x)
            for (int c = 0; c < channels; ++c) m = std::max(m, std::abs(int(a.at(x, y)[c]) - int(b.at(x, y)[c])));
    return m;
}

static size_t dds_size(int w, int h, int mips, size_t block) {
    size_t n = 148;
    for (int m = 0; m < mips; ++m) {
        n += size_t((w + 3) / 4) * size_t((h + 3) / 4) * block;
        w = std::max(1, w / 2);
        h = std::max(1, h / 2);
    }
    return n;
}

