            CHECK(ui.click("Show it on the pitch##kswap", "##tkits", "home") && rt.is_active(7, 0), "on again");
            rt.wait_idle();
            // ---- 2.7: every slot has its own controls and its own saved choices (the away kit sits below the fold: scroll the panel there)
